package com.nirncraft.loot;

import com.nirncraft.NirnCraft;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.Rarity;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.minecraft.core.registries.BuiltInRegistries;
import java.util.function.Supplier;

/**
 * NirnCraft's loot economy (see {@code docs/LOOT.md}): the container taxonomy ({@code nirncraft:containers/<kind>/<tier>},
 * generated by {@code tools/loot_data.py}), the loot level ({@link LootLevels}), material ladders ({@link LootTiers}),
 * loot functions ({@link LootFunctions}), collections ({@link Collectibles}, {@link LegendaryUniques},
 * {@link CollectionTracker}), restocking ({@link Restock}) and the {@code /skyloot} dev command ({@link LootCommand}).
 */
public final class LootModule {
    public static final DeferredRegister<Item> ITEMS = DeferredRegister.create(BuiltInRegistries.ITEM, NirnCraft.MODID);

    /** A Stone of Barenziah, before Vex names it: an "Unusual Gem" (24, one per named dungeon). */
    public static final Supplier<Item> UNUSUAL_GEM = ITEMS.register("unusual_gem",
            () -> new CollectibleItem(CollectibleItem.Kind.GEM, com.nirncraft.platform.SkyProperties.item("unusual_gem").stacksTo(1).rarity(Rarity.UNCOMMON)));
    public static final Supplier<Item> CROWN_OF_BARENZIAH = ITEMS.register("crown_of_barenziah",
            () -> new CollectibleItem(CollectibleItem.Kind.CROWN, com.nirncraft.platform.SkyProperties.item("crown_of_barenziah").stacksTo(1).rarity(Rarity.EPIC)));
    public static final Supplier<Item> BLACK_BOOK = ITEMS.register("black_book",
            () -> new BlackBookItem(com.nirncraft.platform.SkyProperties.item("black_book").stacksTo(1).rarity(Rarity.EPIC)));
    public static final Supplier<Item> ELDER_SCROLL = ITEMS.register("elder_scroll",
            () -> new CollectibleItem(CollectibleItem.Kind.SCROLL, com.nirncraft.platform.SkyProperties.item("elder_scroll").stacksTo(1).rarity(Rarity.EPIC)));
    public static final Supplier<Item> REGIONAL_TREASURE = ITEMS.register("regional_treasure",
            () -> new CollectibleItem(CollectibleItem.Kind.TREASURE, com.nirncraft.platform.SkyProperties.item("regional_treasure").stacksTo(1).rarity(Rarity.RARE)));

    private LootModule() {}

    public static void init(IEventBus modBus) {
        ITEMS.register(modBus);
        AddTableModifier.init(modBus);
        LootFunctions.init(modBus);
        // NirnCraft's own per-player loot containers (docs/CONTAINERS.md), replacing Lootr
        com.nirncraft.loot.container.ContainerRegistry.init(modBus);
        com.nirncraft.NirnCraft.config(net.neoforged.fml.config.ModConfig.Type.LOCAL, com.nirncraft.loot.container.ContainersConfig.SPEC,
                "nirncraft-containers-common.toml");
        com.nirncraft.loot.container.ContainerSelfTest.registerAutorun();
    }
}
